public class ApiNotionBlockProvider : INotionBlockProvider
{
    private readonly HttpClient _http;

    public ApiNotionBlockProvider(HttpClient http) => _http = http;

    public async Task<IEnumerable<IPageBlock>> GetBlocksAsync(string pageId)
        => await _http.GetFromJsonAsync<List<PageBlock>>($"/api/pages/{pageId}/blocks") ?? [];

    public async Task<IPageBlock> CreateBlockAsync(string pageId, IPageBlock block, string? afterBlockId)
    {
        var response = await _http.PostAsJsonAsync($"/api/pages/{pageId}/blocks?after={afterBlockId}", block);
        return await response.Content.ReadFromJsonAsync<PageBlock>() ?? throw new InvalidOperationException();
    }

    // ... implement remaining methods
}

